"""Generate run.sh: the whole PDF -> snapshot pipeline for one project directory."""

from __future__ import annotations

from pathlib import Path
import shlex

import click

# Quoted heredoc: nothing below is expanded by Python except the @@NAME@@ markers.
_TEMPLATE = r"""#!/usr/bin/env bash
# Generated by `deepresearch-flow utils init-run`. Safe to edit and to run again:
# finished chains leave logs/<chain>.done and are skipped.
#   ./run.sh              run everything, then build
#   ./run.sh --only X     X = ocr | simple | deep_read | translate | build
# Environment: NOTIFY_URL (optional, https://host/api/<uuid>/get)
set -u
cd "$(dirname "$0")"
NAME=@@NAME@@
MODEL=@@MODEL@@
LANG_TO=@@LANG@@
CONFIG=@@CONFIG@@
OCR_CONFIG=@@OCR_CONFIG@@
ROUNDS=@@ROUNDS@@
DF="uv run --project @@REPO@@ deepresearch-flow"   # word-split on purpose
PARTIAL=3
export PATH="@@REPO@@/node_modules/.bin:$PATH"   # fix-mermaid needs mmdc
mkdir -p logs

notify() {
  [ -n "${NOTIFY_URL:-}" ] || return 0
  curl -fsS --max-time 10 -G "$NOTIFY_URL" \
    --data-urlencode "format=text" --data-urlencode "msg=$NAME: $1" >/dev/null 2>&1 || true
}

# run_retry "<label>" <first-cmd...> -- <retry-cmd...>
# Exit 0: done. Exit 3: failed items, run the retry command up to ROUNDS times.
# Any other exit code: command broke, stop.
run_retry() {
  local label=$1; shift
  local first=() retry=() cur=first
  for a in "$@"; do
    if [ "$a" = "--" ]; then cur=retry; continue; fi
    if [ $cur = first ]; then first+=("$a"); else retry+=("$a"); fi
  done
  "${first[@]}"; local rc=$?
  local n=0
  while [ $rc -eq $PARTIAL ] && [ $n -lt "$ROUNDS" ]; do
    n=$((n+1)); echo "[$label] retry round $n"
    "${retry[@]}"; rc=$?
  done
  if [ $rc -eq $PARTIAL ]; then echo "[$label] still has failed items after $ROUNDS rounds"; return 0; fi
  return $rc
}

# step "<label>" cmd... : plain command, exit 3 is only a warning.
step() {
  local label=$1; shift
  "$@"; local rc=$?
  [ $rc -eq $PARTIAL ] && { echo "[$label] has failed items"; return 0; }
  return $rc
}

chain_ocr() {
  step ocr $DF recognize ocr pdf --config "$OCR_CONFIG" --output-dir ocr || return 1
  step fix $DF recognize fix --input ocr -r --in-place || return 1
  run_retry fix-math $DF recognize fix-math --input ocr -r --in-place --config "$CONFIG" --model "$MODEL" \
    --report logs/fix-math-ocr.json -- \
    $DF recognize fix-math --input ocr -r --in-place --config "$CONFIG" --model "$MODEL" \
    --report logs/fix-math-ocr.json --retry-failed || return 1
  step organize $DF recognize organize --input ocr -r --output-simple md_simple --output-base64 md_base64
}

# extract keeps intermediate files in ./paper_stage_outputs, so each template has its own cwd.
chain_extract() {
  local t=$1; local d="logs/$t"; mkdir -p "$d"
  local ext=(paper extract --input ../../md_simple --config "$CONFIG" --model "$MODEL" --prompt-template "$t"
    --output "../../$t.json" --errors "../../logs/$t-errors.json")
  (cd "$d" && run_retry "$t" $DF "${ext[@]}" -- $DF "${ext[@]}" --retry-failed) || return 1
  step "fix-$t" $DF recognize fix --input "$t.json" --json --in-place || return 1
  run_retry "fix-math-$t" $DF recognize fix-math --input "$t.json" --json --in-place --config "$CONFIG" --model "$MODEL" \
    --report "logs/fix-math-$t.json" -- \
    $DF recognize fix-math --input "$t.json" --json --in-place --config "$CONFIG" --model "$MODEL" \
    --report "logs/fix-math-$t.json" --retry-failed || return 1
  if [ "$t" = deep_read ]; then
    run_retry fix-mermaid $DF recognize fix-mermaid --input deep_read.json --json --in-place --config "$CONFIG" --model "$MODEL" \
      --report logs/fix-mermaid-deep_read.json -- \
      $DF recognize fix-mermaid --input deep_read.json --json --in-place --config "$CONFIG" --model "$MODEL" \
      --report logs/fix-mermaid-deep_read.json --retry-failed
  fi
}

chain_translate() {
  # translate skips finished outputs, so a retry round is the same command.
  run_retry translate $DF translator translate --input md_base64 --config "$CONFIG" --model "$MODEL" \
    --target-lang "$LANG_TO" --fix-level moderate --output-dir md_base64_translated --debug-dir logs/translator -- \
    $DF translator translate --input md_base64 --config "$CONFIG" --model "$MODEL" \
    --target-lang "$LANG_TO" --fix-level moderate --output-dir md_base64_translated --debug-dir logs/translator || return 1
  step fix-translated $DF recognize fix --input md_base64_translated -r --in-place || return 1
  run_retry fix-math-translated $DF recognize fix-math --input md_base64_translated -r --in-place --config "$CONFIG" --model "$MODEL" \
    --report logs/fix-math-translated.json -- \
    $DF recognize fix-math --input md_base64_translated -r --in-place --config "$CONFIG" --model "$MODEL" \
    --report logs/fix-math-translated.json --retry-failed
}

# run_chain <name> <function> [arg]: writes logs/<name>.done or .failed, never both.
run_chain() {
  local name=$1; shift
  [ -e "logs/$name.done" ] && { echo "[$name] already done"; return 0; }
  rm -f "logs/$name.failed"
  local t0=$SECONDS
  "$@" 2>&1 | tee -a "logs/$name.log"
  if [ "${PIPESTATUS[0]}" -eq 0 ]; then
    touch "logs/$name.done"; notify "$name done ($(( (SECONDS-t0)/60 )) min)"
  else
    touch "logs/$name.failed"; notify "$name FAILED, see logs/$name.log"; return 1
  fi
}

do_build() {
  mkdir -p dist
  local prev=()
  [ -f "dist/$NAME.db" ] && prev=(--previous-snapshot-db "dist/$NAME.db")  # keep paper_id stable
  $DF paper db snapshot build -i simple.json -i deep_read.json -b @@BIB@@ \
    --md-root md_simple --md-translated-root md_base64_translated --pdf-root pdf \
    --output-db "dist/$NAME.db" --static-export-dir "dist/$NAME-export" "${prev[@]}"
}

# Entry point used inside tmux windows: ./run.sh --chain <name>
if [ "${1:-}" = --chain ]; then
  case $2 in
    simple) run_chain simple chain_extract simple ;;
    deep_read) run_chain deep_read chain_extract deep_read ;;
    translate) run_chain translate chain_translate ;;
  esac
  exit $?
fi

ONLY=""
[ "${1:-}" = --only ] && ONLY=${2:-}

want() { [ -z "$ONLY" ] || [ "$ONLY" = "$1" ]; }

want ocr && { run_chain ocr chain_ocr || { notify "stopped at ocr"; exit 1; }; }

if want simple || want deep_read || want translate; then
  command -v tmux >/dev/null || { echo "tmux is required"; exit 1; }
  # A dedicated tmux server inherits this shell's environment (API keys, NOTIFY_URL);
  # an already-running default server would not.
  T="tmux -L drflow-$NAME"; S=run
  # Kill only the session: `kill-server` followed at once by `new-session` races with
  # the dying server and the new session can vanish.
  $T kill-session -t "$S" 2>/dev/null
  $T new-session -d -s "$S" -n main "sleep 86400" >/dev/null 2>&1 </dev/null   # the tmux server must not hold this script's pipes
  for c in simple deep_read translate; do
    want $c || continue
    rm -f "logs/$c.failed"
    $T new-window -d -t "$S:" -n "$c" "./run.sh --chain $c; echo; echo '[$c] finished, press Enter'; read"
  done
  echo "tmux -L drflow-$NAME attach -t $S   (windows: simple deep_read translate)"
  while :; do
    pending=0; failed=0
    for c in simple deep_read translate; do
      want $c || continue
      [ -e "logs/$c.failed" ] && failed=1
      [ -e "logs/$c.done" ] || pending=1
    done
    [ $failed -eq 1 ] && { echo "a chain failed; fix it and run ./run.sh again"; $T kill-window -t "$S:main" 2>/dev/null; exit 1; }
    [ $pending -eq 0 ] && break
    sleep 10
  done
  $T kill-window -t "$S:main" 2>/dev/null
fi

if want build; then
  for c in simple deep_read translate; do
    [ -e "logs/$c.done" ] || { echo "$c not finished; build skipped"; exit 1; }
  done
  if do_build; then notify "build done -> dist/$NAME.db"; else notify "build FAILED"; exit 1; fi
fi
"""


def _find_bib(project: Path) -> Path:
    bibs = sorted(project.glob("*.bib"))
    if len(bibs) != 1:
        raise click.ClickException(
            f"{project} must contain exactly one .bib file, found {len(bibs)}"
        )
    return bibs[0]


@click.command("init-run")
@click.argument("project", type=click.Path(exists=True, file_okay=False, path_type=Path))
@click.option("-m", "--model", required=True, help="provider/model used by every LLM step")
@click.option("--target-lang", default="zh", show_default=True)
@click.option("--config", "config_name", default="config.toml", show_default=True,
              help="LLM config; resolved against the current directory and stored as an absolute path")
@click.option("--ocr-config", "ocr_config_name", default="ocr.toml", show_default=True,
              help="OCR config; resolved like --config")
@click.option("--rounds", default=3, show_default=True, help="Retry rounds per step")
def init_run(
    project: Path,
    model: str,
    target_lang: str,
    config_name: str,
    ocr_config_name: str,
    rounds: int,
) -> None:
    """Write PROJECT/run.sh. PROJECT needs pdf/ and exactly one .bib."""
    project = project.resolve()
    if not (project / "pdf").is_dir():
        raise click.ClickException(f"{project}/pdf not found")
    bib = _find_bib(project)
    repo = Path(__file__).resolve().parents[3]
    script = _TEMPLATE
    for key, value in {
        "NAME": project.name,
        "MODEL": model,
        "LANG": target_lang,
        "CONFIG": str(Path(config_name).resolve()),
        "OCR_CONFIG": str(Path(ocr_config_name).resolve()),
        "ROUNDS": str(rounds),
        "REPO": str(repo),
        "BIB": bib.name,
    }.items():
        script = script.replace(f"@@{key}@@", shlex.quote(value))
    target = project / "run.sh"
    target.write_text(script, encoding="utf-8")
    target.chmod(0o755)
    click.echo(f"wrote {target}")
